import{_ as a,c as s,aU as e,a as r}from"./chunks/framework.DIXiA2XH.js";const p="/assets/jf1.DCeUixWU.jpg",o="/assets/jf2.DbR08lUv.jpg",_="/assets/jhwg01.BvDFwio8.jpg",i="/assets/jhwg02.511GXq1i.jpg",j=JSON.parse('{"title":"最近在玩的一款几何王国小游戏","description":"","frontmatter":{},"headers":[],"relativePath":"note/my-diary/最近在玩的一款几何王国小游戏.md","filePath":"note/my-diary/最近在玩的一款几何王国小游戏.md","lastUpdated":1773326622000}'),n={name:"note/my-diary/最近在玩的一款几何王国小游戏.md"};function c(m,t,d,l,f,g){return r(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="最近在玩的一款几何王国小游戏" tabindex="-1">最近在玩的一款几何王国小游戏 <a class="header-anchor" href="#最近在玩的一款几何王国小游戏" aria-label="Permalink to &quot;最近在玩的一款几何王国小游戏&quot;">​</a></h1><p>分享一下最近玩的一个小游戏《几何王国》，支付宝的，其实上我是一点都不喜欢玩游戏的，充其量就是玩个斗地主和下象棋这类的，像消消乐，王者荣耀，天天酷跑这类的 我一次都没玩过，提不起一点兴趣，但是为什么这次我会玩这个小游戏呢？是因为过年的时候支付宝集福，需要每天玩小游戏做任务才有抽福卡次数，当时应该合作的有很多 小游戏，大概玩了十来个，比如寻道大千，三国冰河时代，这城有良田，向僵尸开炮....等等，都看不懂，就这个几何王国小游戏，能玩明白，知道是干啥的，而且任务好做， 所以就基本上过年那几天每天玩这个游戏。当时也不会玩，瞎玩，玩了大概十来天。升到了80级吧应该，重要的是，我集福卡竟然集齐了，简直不可思议。 玩过2025年集福的小伙伴都知道，这一年的集福卡模式变了，需要集齐5套福卡，金额依次是1.8元（随机）,2.8元（随机），8.8元,88元,288元。但是我们家5个账号都在玩，都是止步到 8.8，我竟然全都集齐了，运气爆棚。有图有真相，感谢支付宝，过年给我发了400块钱的红包。</p><p><img src="'+p+'" alt=""><img src="'+o+'" alt=""></p><p>好了，上面是故事背景，活动结束之后，我还是每天都玩这个游戏，感觉挺有意思的，主要是英雄比较多，设计的建模还挺好看的，五个英雄是一个阵容，里面英雄分精英，传说，神话三种级别。 又分为法师，辅助，射手，战士，刺客，控制，坦克，回血等功能的英雄，每个英雄有大招还有各阶段的小招，到达一定的等级解锁。有主线任务，冒险任务，部落，切磋，决斗场，各种活动周做任务。 还蛮全的，这个小游戏吧，最多让你玩一个小时，把能打的都打了，任务也做完了，基本上你就玩不了了，因为要么你打不过，要么你没次数，反正就是玩不了了。需要等第二天才能玩。 当时有点上头，没办法玩了，再开一个号，然后就发现微信也有，就微信也开始玩了。里面还有聊天室，里面人每天都在聊天，部落也能聊天，大家都很友好，氛围还挺不错。</p><p>玩到现在，玩了半年了，等级153级，战斗力1000k，可以说最垫底的那批人，因为没氪，每天就做做任务领下低保。闲的时候就打开玩玩，把之前玩象棋和刷抖音的时间给了 这个小游戏，你说上头了么，我感觉有稍微那么一点点吧，反正是每天起来第一件事就是做任务，领低保，毕竟我没氪，说没氪也不算准确，准确来说氪了3块钱，给3个号各充了1块，为了能送箱子。看群里也不乏有充几千几万的。 充1块已经是极限。</p><p>其实这个小游戏就是个卡片碰撞类型的，不过我觉得最大的优点是UI设计的不错，英雄建模大招这些很精致。这个算的上我真正意义上的玩过的第一个小游戏了。 刚开始玩的那段时间，每天都很期待明天的到来，因为第二天又可以做任务，领低保，生战力，解锁新技能了。。。</p><p><img src="'+_+'" alt=""><img src="'+i+'" alt=""></p><p>你要说学到了东西么，只能说比较能理解喜欢玩游戏氪金的朋友的心理了，确实有时候打不过人家，真的很想氪一把提升下战力， 任务就差一点点材料得不到，也想氪一把，不过我还是忍住了， ，了解了组队的阵容，法师，射手，战士什么的，感觉那种大型手游应该也是这样设计的吧， 就当是业余时间放松消遣吧。</p>',8)])])}const u=a(n,[["render",c]]);export{j as __pageData,u as default};
